---------Magnitude analysis
-----------This focuses on the impact and importance of the key relevant dimensions to the entire business
-----The insight here include revenue generated by each country and category on the total scale as well as the average scale
-----Net revenue = SUM(gross_revenue), already after refunds (refunds are stored as negative revenue).
-----Orders without a product have no revenue and are excluded.

-----Products and brands by category
SELECT
    category,
    COUNT(*)                 AS product_count,
    COUNT(DISTINCT brand)    AS brand_count
FROM products
GROUP BY category
ORDER BY product_count DESC;


-----Net revenue by country
SELECT
    c.country,
    ROUND(SUM(t.gross_revenue), 2) AS net_revenue
FROM customers c
JOIN transactions t
    ON c.customer_id = t.customer_id
WHERE t.product_id IS NOT NULL
GROUP BY c.country
ORDER BY SUM(t.gross_revenue) DESC;


-----Net revenue by category
SELECT
    p.category,
    ROUND(SUM(t.gross_revenue), 2) AS net_revenue
FROM products p
JOIN transactions t
    ON p.product_id = t.product_id
GROUP BY p.category
ORDER BY SUM(t.gross_revenue) DESC;


-----Average net revenue per order, by category
SELECT
    p.category,
    ROUND(AVG(t.gross_revenue), 2) AS avg_order_value
FROM products p
JOIN transactions t
    ON p.product_id = t.product_id
GROUP BY p.category
ORDER BY AVG(t.gross_revenue) DESC;


--Order count by country
SELECT
    c.country,
    COUNT(t.transaction_id) AS order_count,
    CONCAT(
        CAST(100.0 * COUNT(t.transaction_id) / SUM(COUNT(t.transaction_id)) OVER () AS DECIMAL(5,2)), '%'
    ) AS order_percentage
FROM customers c
JOIN transactions t
    ON c.customer_id = t.customer_id
WHERE t.product_id IS NOT NULL
GROUP BY c.country
ORDER BY order_count DESC;


----Top 10 customers by net revenue (refunds subtracted)
SELECT TOP 10
    c.customer_id,
    ROUND(SUM(t.gross_revenue), 2) AS net_revenue
FROM customers c
JOIN transactions t
    ON c.customer_id = t.customer_id
WHERE t.product_id IS NOT NULL
GROUP BY c.customer_id
ORDER BY SUM(t.gross_revenue) DESC;
